export function IloiloMap({ className = "" }: { className?: string }) {
  return (
    <svg viewBox="0 0 1016 1085" className={className} role="img" aria-label="Map of Iloilo province">
      {regions.map((r, i) => (
        <path
          key={i}
          d={r.d}
          transform={r.transform}
          tabIndex={-1}
          className="map-region"
          style={{ ["--region" as string]: r.color, ["--base" as string]: r.base }}
        />
      ))}
      <g transform="translate(471 871)" className="pointer-events-none">
        <circle r="9" fill="#b50000" className="map-pin-ring" />
        <circle r="6" fill="#b50000" />
        <text x="16" y="6" fontSize="20" fontWeight="700" fill="#1e1e1e">
          Iloilo City
        </text>
      </g>
    </svg>
  );
}
